style.css:
@-moz-document domain("roblox.com") {
/* background behind everything */
  html, body {
    background-color: #40107a !important;
  }

  /* sidebar / navigation / left menu */
  .left-col,
  .side-nav,
  .left-navigation,
  .menu,
  nav,
  .navigation-container,
  .nav-container,
  .nav-menu,
  .rbx-left-col,
  .navigation {
    background-color: #280b4b !important;
  }

  /* top navigation bar */
  .navbar,
  .header,
  .topbar,
  .rbx-navbar,
  #header,
  .rbx-header {
    background-color: #280b4b !important;
  }

  /* cards, panels, sections */
  .card,
  .card-item,
  .game-card,
  .panel,
  .tile,
  .section,
  .section-content,
  .section-header {
    background-color: #280b4b !important;
  }

  /* inline white backgrounds inside panels */
  [style*="background-color:#fff"],
  [style*="background-color: #fff"],
  [style*="background-color: rgb(255,255,255)"],
  [style*="background-color: rgb(255, 255, 255)"] {
    background-color: #280b4b !important;
  }

  /* text color remains unchanged */
  * { color: inherit !important; }
}
